import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Input,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomSwitch,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import makeAnimated from "react-select/animated";
import retailerReceiptsApi from "../../../api/retailers/retailerReceiptsApi";
import productsApi from "../../../api/productsApi";
import entitiesApi from "../../../api/entitiesApi";
import discountsApi from "../../../api/discountsApi";
import dayjs from "dayjs";
import "dayjs/locale/en-gb";
import { Modal } from "antd";

export default function InventoryFormModal({
  ismodalOpen,
  setisModalOpen,
  inventoryToEdit,
  modalTitle = "Add new retail inventory",
  updated,
  setUpdated,
}) {
  const moment = require("moment");
  const animatedComponent = makeAnimated();
  const [retailerReceipt, setRetailerReceipt] = useState(
    inventoryToEdit ? inventoryToEdit : null
  );
  const [errors, setErrors] = useState();
  const retailerReceiptsActionsApi = useApi(
    retailerReceiptsApi.retailerReceiptsActionAdmin
  );

  const handleRetailerReceiptAction = async (data) => {
    await retailerReceiptsActionsApi.request(data);

    // if (result.ok) {
    //   setUpdated(true);
    //   setisModalOpen(setUpdated);
    // } else {
    //   setErrors(result.data.errors);
    //   setUpdated(false);
    // }
    // console.log("res at create receipt", result);
  };

  useEffect(() => {}, [retailerReceipt]);

  useEffect(() => {
    if (retailerReceiptsActionsApi.data) {
      if (retailerReceiptsActionsApi.data.retailer_receipt) {
        setRetailerReceipt(retailerReceiptsActionsApi.data.retailer_receipt);
        toast.success(retailerReceiptsActionsApi.data.response_message)
        setUpdated(true)
        setisModalOpen(false)
      }

      if (retailerReceiptsActionsApi.data.errors) {
        setErrors(retailerReceiptsActionsApi.data.errors);
      }
    }

    console.log("retailerReceiptsActionsApi.data", retailerReceiptsActionsApi.data)
  }, [retailerReceiptsActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      manufacture_date: retailerReceipt
        ? retailerReceipt.manufacture_date
        : moment(new Date()).format("YYYY-MM-DD"),
      expiry_date: retailerReceipt
        ? retailerReceipt.expiry_date
        : moment(new Date()).format("YYYY-MM-DD"),
      batch: retailerReceipt ? retailerReceipt.batch : "",
      bar_code: retailerReceipt ? retailerReceipt.bar_code : "",
      unit_quantity: retailerReceipt ? retailerReceipt.unit_quantity : "",
      pack_buying_price: retailerReceipt
        ? retailerReceipt.pack_buying_price
        : "",
      unit_of_receipt: retailerReceipt
        ? retailerReceipt.unit_of_receipt
        : "PIECE",
      is_bulky: retailerReceipt ? retailerReceipt.is_bulky : "false",
      unit_selling_price: retailerReceipt
        ? retailerReceipt.unit_selling_price
        : "",
      unit_price_discount: retailerReceipt
        ? retailerReceipt.unit_price_discount
        : "",
      received_from: retailerReceipt
        ? {
            label: retailerReceipt.received_from_title,
            value: retailerReceipt.received_from,
          }
        : null,
      product: retailerReceipt
        ? {
            label: retailerReceipt.product_title,
            value: retailerReceipt.product,
          }
        : null,
      price_discount: retailerReceipt
        ? {
            label: retailerReceipt.price_discount_title,
            value: retailerReceipt.price_discount,
          }
        : null,
      quantity_discount: retailerReceipt
        ? {
            label: retailerReceipt.quantity_discount_title,
            value: retailerReceipt.quantity_discount,
          }
        : null,
    },

    validationSchema: Yup.object({
      unit_quantity: Yup.number().min(0).required("Title is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (inventoryToEdit) {
        handleRetailerReceiptAction({
          action: "UpdateRetailerReceipt",
          retailer_receipt: inventoryToEdit.id,
          retailer_receipt_details: {
            product: values.product.value,
            unit_quantity: values.unit_quantity ? values.unit_quantity : 0,
            unit_of_receipt: values.unit_of_receipt.value,
            is_bulky: values.is_bulky,
            pack_buying_price: values.pack_buying_price,
            unit_selling_price: values.unit_selling_price,
            unit_price_discount: values.unit_price_discount,
            received_from: values.received_from
              ? values.received_from.value
              : "",
            manufacture_date: values.manufacture_date,
            expiry_date: values.expiry_date,
            batch: values.batch,
            bar_code: values.bar_code,
            quantity_discount: values.quantity_discount
              ? values.quantity_discount.value
              : "",
            price_discount: values.price_discount
              ? values.price_discount.value
              : "",
          },
        });
      } else {
        handleRetailerReceiptAction({
          action: "CreateRetailerReceipt",
          retailer_receipt_details: {
            product: values.product.value,
            unit_quantity: values.unit_quantity ? values.unit_quantity : 0,
            unit_of_receipt: values.unit_of_receipt.value ? values.unit_of_receipt.value : "PIECE",
            is_bulky: values.is_bulky,
            pack_buying_price: values.pack_buying_price,
            unit_selling_price: values.unit_selling_price,
            unit_price_discount: values.unit_price_discount,
            received_from: values.received_from
              ? values.received_from.value
              : "",
            manufacture_date: values.manufacture_date,
            expiry_date: values.expiry_date,
            batch: values.batch,
            bar_code: values.bar_code,
            quantity_discount: values.quantity_discount
              ? values.quantity_discount.value
              : null,
            price_discount: values.price_discount
              ? values.price_discount.value
              : null,
          },
        });
      }

      // resetForm();
    },
  });

  //Load products

  const searchProductsApi = useApi(productsApi.productsAction);

  const searchProducts = async (data) => {
    await searchProductsApi.request(data);
  };
  const [products, setProducts] = useState();
  const loadProductsOptions = async (inputText = "", callback) => {
    searchProducts({
      action: "SearchProducts",
      searchQuery: inputText,
    });
    callback(products.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchProductsApi.data) {
      if (searchProductsApi.data.length) {
        setProducts(searchProductsApi.data);
      }
    }
    console.log("searchProductsApi.data", searchProductsApi.data);
  }, [searchProductsApi.data]);

  //Load wholesalers

  const searchEntitiesApi = useApi(entitiesApi.entitiesAction);
  const [switchLabel, setswitchLabel] = useState("Not Bulky");
  const searchEntities = async (data) => {
    await searchEntitiesApi.request(data);
  };
  const [sources, setSources] = useState();
  const loadSourcesOptions = async (inputText = "", callback) => {
    searchEntities({
      action: "SearchEntities",
      searchQuery: inputText,
    });
    callback(sources.map((i) => ({ label: i.title, value: i.id })));
  };

  useEffect(() => {
    if (searchEntitiesApi.data) {
      if (searchEntitiesApi.data.length) {
        setSources(searchEntitiesApi.data);
      }
    }
    console.log("searchManufacturerApi.data", searchEntitiesApi.data);
  }, [searchEntitiesApi.data]);




  const handleManfactureDateChange = (date, dateString) => {
    formik.setFieldValue("manufacture", dateString);
  };
  const handleExpiryDateChange = (date, dateString) => {
    formik.setFieldValue("expiry_date", dateString);
  };

  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  const handleSwitchChange = (checked) => {

    formik.setFieldValue("is_bulky", checked ? "true" : "false");
    setswitchLabel(checked ? "Is Bulky" : "Not Bulk");

    // console.log('eee', e.target.checked)
  };

  return (
    <div className="w-full">
      <Modal
        maskClosable={false}
        width={800}
        className="w-full text-center uppercase"
        title={inventoryToEdit ? `EDIT ${inventoryToEdit.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-1 md:grid-cols-2 mt-5 gap-1 ">
            <CustomFormItem
              touched={formik.touched.product}
              error={formik.errors.product}
            >
              <CustomSelectAsyncSelect
                className="text-start"
                name="product"
                id="product"
                label="Select product item"
                size="large"
                onChange={(value) => formik.setFieldValue("product", value)}
                value={formik.values.product}
                placeholder="Type product name and select"
                loadOptions={loadProductsOptions}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.received_from}
              error={formik.errors.received_from}
            >
              <CustomSelectAsyncSelect
                className="text-start"
                name="received_from"
                id="received_from"
                label="Select supplier"
                size="large"
                onChange={(value) =>
                  formik.setFieldValue("received_from", value)
                }
                value={formik.values.received_from}
                placeholder="Select  supplier"
                loadOptions={loadSourcesOptions}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.unit_quantity}
              error={formik.errors.unit_quantity}
            >
              <CustomInput
                required={true}
                label="Enter unit quantity"
                id="unit_quantity"
                name="unit_quantity"
                onChange={formik.handleChange}
                placeholder="Enter unit quantity"
                size="large"
                type="number"
                value={formik.values.unit_quantity}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.pack_buying_price}
              error={formik.errors.pack_buying_price}
            >
              <CustomInput
                required={true}
                label="Enter pack buying price"
                id="pack_buying_price"
                name="pack_buying_price"
                onChange={formik.handleChange}
                placeholder="Enter pack buying  (Enter 0 if not known)"
                size="large"
                type="number"
                value={formik.values.pack_buying_price}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.unit_selling_price}
              error={formik.errors.unit_selling_price}
            >
              <CustomInput
                required={true}
                label="Enter unit_selling_price"
                id="unit_selling_price"
                name="unit_selling_price"
                onChange={formik.handleChange}
                placeholder="Enter unit selling price"
                size="large"
                type="number"
                value={formik.values.unit_selling_price}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.unit_price_discount}
              error={formik.errors.unit_price_discount}
            >
              <CustomInput
                required={true}
                label="Enter pack price discount"
                id="unit_price_discount"
                name="unit_price_discount"
                onChange={formik.handleChange}
                placeholder="Enter pack price discount"
                size="large"
                type="number"
                value={formik.values.unit_price_discount}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.batch}
              error={formik.errors.batch}
            >
              <CustomInput
                label="Enter batch number"
                id="batch"
                name="batch"
                onChange={formik.handleChange}
                placeholder="Enter batch number"
                size="large"
                type="number"
                value={formik.values.batch}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.bar_code}
              error={formik.errors.bar_code}
            >
              <CustomInput
                label="Enter bar code"
                id="bar_code"
                name="bar_code"
                onChange={formik.handleChange}
                placeholder="Enter bar code"
                size="large"
                type="text"
                value={formik.values.bar_code}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.manufacture_date}
              error={formik.errors.manufacture_date}
            >
              <CustomDatePicker
                id="manufacture_date"
                name="manufacture_date"
                size="large"
                defaultValue={dayjs(
                  formik.values.manufacture_date,
                  "YYYY-MM-DD"
                )}
                placeholder="Select manufacture date"
                onChange={handleManfactureDateChange}
                value={formik.values.manufacture_date}
                label="Select manufacture date"
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.expiry_date}
              error={formik.errors.expiry_date}
            >
              <CustomDatePicker
                defaultValue={dayjs(formik.values.expiry_date, "YYYY-MM-DD")}
                id="expiry_date"
                name="expiry_date"
                size="large"
                placeholder="Select expiry date"
                onChange={handleExpiryDateChange}
                value={formik.values.expiry_date}
                label="Select expiry date"
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.is_bulky}
              error={formik.errors.is_bulky}
            >
              <CustomSwitch
                id="is_bulky"
                checked={formik.values.is_bulky === "true"}
                onChange={(e) => handleSwitchChange(e)}
                title={switchLabel}
              />
            </CustomFormItem>

            {formik.values.is_bulky === "true" ? <CustomFormItem
              touched={formik.touched.unit_of_receipt}
              error={formik.errors.unit_of_receipt}
            >
              <CustomSelectReactSelect
                name="unit_of_receipt"
                id="unit_of_receipt"
                label="Unit of receipt"
                size="large"
                onChange={(e) => formik.setFieldValue("unit_of_receipt", e)}
                value={formik.values.unit_of_receipt}
                placeholder="Select unit of receipt"
                options={[
                  { value: "GRAM", label: "GRAM" },
                  { value: "KILOGRAM", label: "KILOGRAM" },
                  { value: "LITRE", label: "LITRE" },
                  { value: "PIECE", label: "PIECE" },
                ]}
              />
            </CustomFormItem> : <></>}
          </div>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
